using System.Reflection;
using System.Runtime.Versioning;
using TruePath.PathIoGenerator;
using TruePath.SystemIo;

namespace TruePath.Tests;

/// <summary>
///     Verifies that every path-taking public static API of <see cref="File"/> and <see cref="Directory"/> is
///     exposed by <see cref="PathIo"/>: either generated by the TruePath.PathIoGenerator source generator,
///     provided by a hand-written member, or deliberately excluded via path-io-exclusions.txt. This mirrors the
///     generator rules, so a drift between them shows up as a failing assertion.
/// </summary>
public class PathIoCompletenessTests
{
    [Fact]
    public void EveryPathTakingBclApiIsExposedByPathIo()
    {
        // Reflection over the runtime BCL only matches the compiled PathIo API when the running runtime is of the
        // same major version as the target framework TruePath.SystemIo was built for.
        var frameworkName = typeof(PathIo).Assembly.GetCustomAttribute<TargetFrameworkAttribute>()!.FrameworkName;
        var targetFrameworkMajor = int.Parse(frameworkName.Split('v')[^1].Split('.')[0]);
        if (Environment.Version.Major != targetFrameworkMajor)
        {
            Assert.Skip(
                $"The runtime ({Environment.Version}) does not match the target framework of TruePath.SystemIo ({frameworkName}).");
        }

        var exclusions = LoadExclusions();
        var pathIoMethods = typeof(PathIo)
            .GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly)
            .ToList();

        foreach (var bclMethod in new[] { typeof(File), typeof(Directory) }
                     .SelectMany(type => type.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly))
                     .Where(method => !method.IsGenericMethod))
        {
            var parameters = bclMethod.GetParameters();
            var pathOrdinals = parameters
                .Select((parameter, index) => (parameter, index))
                .Where(pair => pair.parameter.ParameterType == typeof(string)
                               && PathIoRules.IsPathParameterName(pair.parameter.Name!))
                .Select(pair => pair.index)
                .ToHashSet();
            if (pathOrdinals.Count == 0 || !pathOrdinals.Contains(0)) continue; // Not representable as an extension.

            var docId = DocId(bclMethod);
            if (exclusions.Contains(docId)) continue;

            var expectedParameterTypes = parameters
                .Select((parameter, index) => pathOrdinals.Contains(index)
                    ? "TruePath.AbsolutePath"
                    : DocIdType(parameter.ParameterType))
                .ToList();

            var match = pathIoMethods.FirstOrDefault(method =>
                method.Name == bclMethod.Name
                && method.GetParameters().Length == expectedParameterTypes.Count
                && method.GetParameters().Select((parameter, index) => (parameter, index))
                    .All(pair => PathIoParameterType(pair.parameter) == expectedParameterTypes[pair.index]));

            Assert.True(
                match != null,
                $"No PathIo counterpart for {docId}: add a hand-written or generated member, "
                + "or exclude the method in TruePath.SystemIo/path-io-exclusions.txt.");
        }
    }

    private static string PathIoParameterType(ParameterInfo parameter)
    {
        return parameter.ParameterType == typeof(AbsolutePath) ? "TruePath.AbsolutePath" : DocIdType(parameter.ParameterType);
    }

    private static HashSet<string> LoadExclusions()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory != null && !File.Exists(Path.Combine(directory.FullName, "TruePath.sln")))
            directory = directory.Parent;

        if (directory == null) Assert.Skip("Repository root with TruePath.sln not found.");

        return File.ReadAllLines(Path.Combine(directory!.FullName, "TruePath.SystemIo", "path-io-exclusions.txt"))
            .Select(line => line.Trim())
            .Where(line => line.Length > 0 && !line.StartsWith("#", StringComparison.Ordinal))
            .ToHashSet();
    }

    private static string DocId(MethodInfo method)
    {
        return $"M:{method.DeclaringType!.FullName}.{method.Name}({string.Join(",", method.GetParameters().Select(p => DocIdType(p.ParameterType)))})";
    }

    /// <summary>Renders types in the same shape the generator uses for its XML documentation IDs.</summary>
    private static string DocIdType(Type type)
    {
        if (type.IsArray) return DocIdType(type.GetElementType()!) + "[]";

        if (type.IsGenericType)
        {
            var definition = type.GetGenericTypeDefinition();
            var name = definition.FullName!;
            var arity = definition.GetGenericArguments().Length;
            name = name.Substring(0, name.IndexOf('`'));
            return name + "{" + string.Join(",", type.GetGenericArguments().Select(DocIdType)) + "}";
        }

        return type.FullName!;
    }
}
